class ComplaintDraft { const ComplaintDraft({required this.studentProfileId, required this.categoryCode, required this.description, required this.clientRequestId}); final String studentProfileId; final String categoryCode; final String description; final String clientRequestId; bool get isValid => studentProfileId.isNotEmpty && categoryCode.isNotEmpty && description.isNotEmpty; }
class ComplaintRepository { Future<String> submit(ComplaintDraft draft) async => draft.isValid ? 'CMP-2026-0001' : 'invalid'; Future<List<String>> tracking() async => const ['CMP-2026-0001 received', 'CMP-2026-0002 escalated']; }
